"""Single-round and k-round soundness of the graph-3-colouring protocol."""
from __future__ import annotations
from fractions import Fraction
from typing import Dict, List, Sequence, Tuple

Pair = Tuple[int, int]


def is_proper(edges: Sequence[Pair], colouring: Dict[int, int]) -> bool:
    return all(colouring[u] != colouring[v] for (u, v) in edges)


def catch_probability(edges: Sequence[Pair], colouring: Dict[int, int]) -> Fraction:
    """Probability a random edge catches the prover; >= 1/|E| when improper."""
    m = len(edges)
    caught = sum(1 for (u, v) in edges if colouring[u] == colouring[v])
    return Fraction(caught, m)


def kround_cheat_bound(m: int, k: int) -> Fraction:
    """Worst-case k-round cheating probability for one bad edge: ((m-1)/m)^k."""
    return Fraction(m - 1, m) ** k


if __name__ == "__main__":
    edges: List[Pair] = [(0, 1), (1, 2), (2, 0)]           # triangle
    print("proper:", catch_probability(edges, {0: 0, 1: 1, 2: 2}))
    print("one bad edge:", catch_probability(edges, {0: 0, 1: 0, 2: 1}))
    for k in [1, 5, 10, 20, 40]:
        print(f"k={k}: cheat <= {float(kround_cheat_bound(3, k)):.3e}")

"""Perfect honest-verifier zero knowledge for the 3-colouring protocol."""
from __future__ import annotations
from fractions import Fraction
from itertools import permutations, product
from typing import Dict, List, Tuple

Pair = Tuple[int, int]
Perm = Tuple[int, int, int]


def distinct_pairs() -> List[Pair]:
    return [(x, y) for (x, y) in product(range(3), range(3)) if x != y]


def real_distribution(a: int, b: int) -> Dict[Pair, Fraction]:
    """Pushforward of uniform S_3 under pi |-> (pi(a), pi(b))."""
    assert a != b
    perms: List[Perm] = list(permutations(range(3)))  # type: ignore[arg-type]
    dist: Dict[Pair, Fraction] = {}
    for perm in perms:
        key = (perm[a], perm[b])
        dist[key] = dist.get(key, Fraction(0)) + Fraction(1, len(perms))
    return dist


def simulator_distribution() -> Dict[Pair, Fraction]:
    pairs = distinct_pairs()
    return {p: Fraction(1, len(pairs)) for p in pairs}


if __name__ == "__main__":
    sim = simulator_distribution()
    for (a, b) in [(0, 1), (1, 2), (0, 2)]:
        print(f"edge ({a},{b}): real == simulator ? {real_distribution(a, b) == sim}")
    print("each distinct pair has probability", real_distribution(0, 1)[(0, 1)])

