function ROUNDS_FOR_ERROR(n, e, target):
    assert e < n
    prob <- 1
    k <- 0
    while prob > target:
        prob <- prob * (e / n)      # independence: multiply per-round survival
        k <- k + 1
    return k

function SURVIVAL(n, e, k):
    return (e / n)^k                # = #(A_1 x..x A_k) / n^k

function CATCH_PROBABILITY(edges, colouring):
    caught <- 0
    for (u, v) in edges:
        if colouring[u] == colouring[v]:
            caught <- caught + 1
    return caught / |edges|          # >= 1/|edges| iff colouring improper

